import { cachedLogs, previousEvents } from './event-store.js';
import { contractInterface, decodeLog, compareLogs, ChainDataError } from './client.js';

// History is indexed by accepted daily requests, never by elapsed wall resets. Retries reuse
// the current day; only the first request after a completed daily opens the next one.
export function indexLogicalDays(events, { deployBlock, currentDay, head, startDay = 1 }) {
  const starts = new Map([[startDay, {blockNumber:Number(deployBlock)}]]);
  let day = startDay, complete = true;
  for (const event of [...events].sort(compareLogs)) {
    if (event.name === 'DailySessionCompleted') {
      if (Number(event.args.day) === day) complete = true;
    } else if (event.name === 'Advance' && Number(event.args.stage) === 1 && complete && day < currentDay) {
      starts.set(++day, event);
      complete = false;
    } else if (event.name === 'DailyRngApplied' && Number(event.args.day) !== day) {
      throw new ChainDataError('Daily history is incomplete; retry the chain read.');
    }
  }
  if (day !== currentDay) throw new ChainDataError('Daily request history does not match the current game day.');
  return new Map([...starts].map(([n, start]) => {
    const end = starts.get(n + 1);
    return [n, {fromBlock:Number(start.blockNumber), toBlock:end ? Number(end.blockNumber) : Number(head),
      fromEvent:n === 1 ? null : start, toEvent:end ?? null}];
  }));
}

/** A recent day needs only the completed predecessor, not every request since deployment. */
export async function logicalDayRange(snapshot, day) {
  const covering = snapshot.recentLogicalDays?.find(read => read.first <= day);
  if (covering) return (await covering.promise).get(day)
    ?? { fromBlock: snapshot.block.number + 1, toBlock: snapshot.block.number };
  const read = { first: day, promise: resolveRecentDays(snapshot, day) };
  snapshot.recentLogicalDays ??= [];
  snapshot.recentLogicalDays.push(read);
  read.promise.catch(() => {
    snapshot.recentLogicalDays = snapshot.recentLogicalDays.filter(item => item !== read);
  });
  return (await read.promise).get(day)
    ?? { fromBlock: snapshot.block.number + 1, toBlock: snapshot.block.number };
}

async function resolveRecentDays(snapshot, day) {
  const currentDay = Number(await snapshot.field('GAME', 'dailyIdx'));
  if (day > currentDay) return new Map();
  // Bootstrap day one has no completion event; retain the complete validator
  // for that boundary and for older deployments without a predecessor anchor.
  if (day > 2) {
    const boundary = { blockNumber: snapshot.block.number,
      transactionIndex: Number.MAX_SAFE_INTEGER, logIndex: Number.MAX_SAFE_INTEGER };
    const completed = (await previousEvents(snapshot.client, 'GAME', 'DailySessionCompleted', boundary,
      { filters: { day: day - 1 } })).at(-1);
    if (completed) {
      const iface = await contractInterface('GAME');
      const logs = await cachedLogs(snapshot, {
        address: snapshot.client.address('GAME'),
        topics: [['Advance', 'DailyRngApplied', 'DailySessionCompleted'].map(name => iface.getEvent(name).topicHash)],
      }, { fromBlock: completed.blockNumber });
      const events = logs.filter(log => compareLogs(log, completed) > 0)
        .map(log => ({ ...log, ...decodeLog(iface, log) }));
      const ranges = indexLogicalDays(events, { startDay: day - 1,
        deployBlock: completed.blockNumber, currentDay, head: snapshot.block.number });
      const range = ranges.get(day);
      if (!range) throw new ChainDataError('Daily request history does not include the requested day.');
      return ranges;
    }
  }
  return logicalDayRanges(snapshot);
}

export async function logicalDayRanges(snapshot) {
  if (!snapshot.logicalDays) {
    const pending = (async () => {
      const iface = await contractInterface('GAME');
      const currentDay = Number(await snapshot.field('GAME', 'dailyIdx'));
      const logs = currentDay <= 1 ? [] : await cachedLogs(snapshot, {
        address: snapshot.client.address('GAME'),
        topics: [['Advance', 'DailyRngApplied', 'DailySessionCompleted'].map(name => iface.getEvent(name).topicHash)],
      }, { fromBlock: Number(snapshot.client.chain.deployBlock) });
      return indexLogicalDays(logs.map(log => ({ ...log, ...decodeLog(iface, log) })), {
        currentDay, deployBlock: snapshot.client.chain.deployBlock, head: snapshot.block.number,
      });
    })();
    snapshot.logicalDays = pending;
    pending.catch(() => { if (snapshot.logicalDays === pending) snapshot.logicalDays = null; });
  }
  return snapshot.logicalDays;
}
